import defaultCv from './default-cv.json';
import defaultCvEn from './default-cv-en.json';
import defaultCvJob from './default-cv-job.json';
import defaultCvEnJob from './default-cv-en-job.json';
import defaultCvBroad from './default-cv-broad.json';
import defaultCvBroadEn from './default-cv-broad-en.json';
import defaultCvBroadJob from './default-cv-broad-job.json';
import defaultCvBroadEnJob from './default-cv-broad-en-job.json';
import defaultCvWebmaster from './default-cv-webmaster.json';
import defaultCvWebmasterEn from './default-cv-webmaster-en.json';
import defaultCvWebmasterJob from './default-cv-webmaster-job.json';
import defaultCvWebmasterEnJob from './default-cv-webmaster-en-job.json';
import './style.css';
import './enhancements.css';
import './refinements.css';

const KEY = 'cv-adapt-cv-v1';
const DESIGN_KEY = 'cv-adapt-default-design';
const savedDefaultDesign = localStorage.getItem(DESIGN_KEY) || 'studio';
const settings = { template: savedDefaultDesign, defaultTemplate: savedDefaultDesign, font: 14, margin: 10, line: 1.3, photo: true, coverLetter: false, editMode: false, hideSummary: false, hideSkills: false, hideLanguages: false, hideCertifications: false, hideExperience: false, hideEducation: false, hideLinkedin: false, hideWebsite: false, hidePhone: false, hideLocation: false };
const state = {
  cv: JSON.parse(localStorage.getItem(KEY) || JSON.stringify(defaultCv)),
  job: 'We are looking for a Digital Marketing Lead to own SEO strategy, content operations, lifecycle marketing, and reporting. You will lead a small team, partner with product, and grow qualified pipeline through data-informed experiments.',
  priority: '', tab: 'adapted', jsonError: '', aiProvider: localStorage.getItem('cv-adapt-provider') || 'gemini', track: localStorage.getItem('cv-adapt-track') || 'alternance', variant: localStorage.getItem('cv-adapt-variant') || 'growth', adapted: false
};

const $ = (s, root = document) => root.querySelector(s);
const esc = (v = '') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean = v => String(v || '').replace(/[–—]/g, '-');
const save = () => localStorage.setItem(KEY, JSON.stringify(state.cv));
if (state.cv.personal?.photo === 'profile-default.png') { state.cv.personal.photo = 'profile-default.jpg'; save(); }
if (state.cv.personal && !state.cv.personal.website) { state.cv.personal.website = 'growthmaker.fr'; save(); }
const avatar = () => state.cv.personal.photo || 'profile-avatar.svg';
const cloneCv = cv => JSON.parse(JSON.stringify(cv));
function isEnglishJob(){const text=String(state.job||'').toLowerCase();const english=(text.match(/\b(the|and|with|role|experience|skills|requirements|company|responsibilities|marketing|looking)\b/g)||[]).length;const french=(text.match(/\b(le|la|les|des|avec|poste|compétences|expérience|recherche|entreprise)\b/g)||[]).length;return english>french;}
function targetLanguage(){return isEnglishJob()?'English':'French';}
function jobTitle(){const text=String(state.job||'').replace(/\s+/g,' ').trim();const match=text.match(/(?:looking for|hiring|recherche|poste (?:de|d')|position (?:of|de))\s+(?:a |an |un |une )?([^,.!;]+)/i);const raw=(match?.[1]||state.cv.personal.role||'CV').trim();return raw.split(/\b(?:to|who|with|responsible|for|pour|afin|avec|qui|en charge)\b/i)[0].replace(/\s+/g,' ').trim();}
function slug(value){return String(value||'cv').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'').toLowerCase();}
function filenamePart(value){const acronyms=new Set(['SEO','SEA','ASO','GA4','GTM','AI','IA','CRM','CRO']);return slug(value).split('-').filter(Boolean).map(word=>acronyms.has(word.toUpperCase())?word.toUpperCase():word[0].toUpperCase()+word.slice(1)).join('_');}
function suggestedFilename(){const title=state.cv.personal.role||jobTitle();return `CV_${filenamePart(state.cv.personal.name)}_${filenamePart(title)}`;}
function renderFilename(){const tabs=$('.tabs');if(!tabs)return;$('.filename-row')?.remove();tabs.insertAdjacentHTML('beforebegin',`<div class="filename-row"><span>Suggested file name</span><code>${esc(suggestedFilename())}</code><button class="button filename-copy" id="copy-filename">Copy name</button></div>`);}
function addTemplateChoices(){const grid=$('.template-grid');if(!grid||grid.querySelector('[data-template="executive"]'))return;grid.insertAdjacentHTML('beforeend','<button class="template" data-template="executive"><span class="template-swatch executive"></span>Executive</button><button class="template" data-template="modern"><span class="template-swatch modern"></span>Modern</button>');}
function addDefaultDesignControl(){const grid=$('.template-grid');if(!grid||$('.default-design-control'))return;const selected=settings.template[0].toUpperCase()+settings.template.slice(1);const preferred=settings.defaultTemplate[0].toUpperCase()+settings.defaultTemplate.slice(1);grid.insertAdjacentHTML('afterend','<div class="default-design-control"><button class="button secondary" id="set-default-template">Use '+esc(selected)+' as my default design</button><small>Current default: '+esc(preferred)+'</small></div>');}
function setDefaultDesign(){settings.defaultTemplate=settings.template;localStorage.setItem(DESIGN_KEY,settings.defaultTemplate);shell();toast(settings.defaultTemplate[0].toUpperCase()+settings.defaultTemplate.slice(1)+' is now your default design.');}
function defaultCvFor(language,track='alternance',variant=state.variant||'growth'){if(variant==='broad'){return language==='en'?(track==='job'?defaultCvBroadEnJob:defaultCvBroadEn):(track==='job'?defaultCvBroadJob:defaultCvBroad);}if(variant==='webmaster'){return language==='en'?(track==='job'?defaultCvWebmasterEnJob:defaultCvWebmasterEn):(track==='job'?defaultCvWebmasterJob:defaultCvWebmaster);}return language==='en'?(track==='job'?defaultCvEnJob:defaultCvEn):(track==='job'?defaultCvJob:defaultCv);}
function loadDefaultCv(language,track='alternance',variant=state.variant||'growth',withCoverLetter=false){state.variant=variant;state.track=track;localStorage.setItem('cv-adapt-variant',variant);localStorage.setItem('cv-adapt-track',track);state.cv=cloneCv(defaultCvFor(language,track,variant));if(withCoverLetter){settings.coverLetter=true;if(!state.cv.coverLetter)state.cv.coverLetter={};}save();shell();const vLabel=variant==='broad'?'Broad Digital Marketing':variant==='webmaster'?'Webmaster & CMS':'Growth & SEO';toast(`${language==='en'?'English':'French'} ${vLabel} (${track==='job'?'regular job':'alternance'})${withCoverLetter?' + cover letter':''} loaded.`);}
function addTopDefaults(){const meta=$('.top-meta');if(!meta||$('.top-defaults'))return;const cvIcon=`<svg viewBox="0 0 16 16" width="11" height="11" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1px;margin-right:3px"><rect x="2" y="1" width="12" height="14" rx="1.5"/><line x1="5" y1="5" x2="11" y2="5"/><line x1="5" y1="8" x2="11" y2="8"/><line x1="5" y1="11" x2="8.5" y2="11"/></svg>`;const clIcon=`<svg viewBox="0 0 16 16" width="11" height="11" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1px;margin-right:3px"><rect x="2" y="1" width="12" height="14" rx="1.5"/><line x1="5" y1="4.5" x2="11" y2="4.5"/><line x1="5" y1="7" x2="11" y2="7"/><line x1="5" y1="9.5" x2="11" y2="9.5"/><line x1="5" y1="12" x2="9" y2="12"/><path d="M9.5 1.5 v2.5 h2.5" stroke-dasharray="2 1"/></svg>`;const mkBtns=(v,cl)=>['growth','broad','webmaster'].map(variant=>{const vShort=variant==='broad'?'Broad':variant==='webmaster'?'Web.':'Growth';const suffix=cl?'-cl':'';return `<div class="menu-section-title">${variant==='broad'?'Broad Digital Marketing':variant==='webmaster'?'Webmaster & CMS':'Growth & SEO'}</div><button data-default-profile="fr-alternance-${variant}${suffix}">FR Alternance</button><button data-default-profile="en-alternance-${variant}${suffix}">EN Alternance</button><button data-default-profile="fr-job-${variant}${suffix}">FR Regular job</button><button data-default-profile="en-job-${variant}${suffix}">EN Regular job</button>`;}).join('');meta.insertAdjacentHTML('afterbegin',`<details class="top-defaults"><summary class="button secondary">Default CVs ▾</summary><div class="top-defaults-menu"><div class="menu-tab-row"><button class="menu-tab active" id="tab-cv">CV</button><button class="menu-tab" id="tab-cl">Lettre de motivation</button></div><div id="menu-panel-cv">${mkBtns(false,false)}</div><div id="menu-panel-cl" style="display:none">${mkBtns(true,true)}</div></div></details>`);$('#tab-cv')?.addEventListener('click',e=>{$('#menu-panel-cv').style.display='';$('#menu-panel-cl').style.display='none';e.target.classList.add('active');$('#tab-cl').classList.remove('active');});$('#tab-cl')?.addEventListener('click',e=>{$('#menu-panel-cv').style.display='none';$('#menu-panel-cl').style.display='';e.target.classList.add('active');$('#tab-cv').classList.remove('active');});}
function addPromptModes(){const alternance=$('#copy-prompt');if(!alternance||$('#copy-prompt-job'))return;alternance.textContent='Copy alternance AI prompt';alternance.insertAdjacentHTML('afterend','<button class="button copy-ai" id="copy-prompt-job">Copy regular-job AI prompt</button>');}
function addDefaultSourceControls(){const group=$('.cv-language-actions');if(!group||group.querySelector('[data-default-profile]'))return;group.classList.add('cv-default-grid');group.innerHTML=`<div style="grid-column:1/-1;font-weight:700;font-size:10px;margin-top:2px;color:#17687a;text-transform:uppercase">Growth & SEO</div><button class="button secondary" data-default-profile="fr-alternance-growth">FR alternance</button><button class="button secondary" data-default-profile="en-alternance-growth">EN alternance</button><button class="button secondary" data-default-profile="fr-job-growth">FR job</button><button class="button secondary" data-default-profile="en-job-growth">EN job</button><div style="grid-column:1/-1;font-weight:700;font-size:10px;margin-top:6px;color:#17687a;text-transform:uppercase">Broad Digital Marketing</div><button class="button secondary" data-default-profile="fr-alternance-broad">FR alternance</button><button class="button secondary" data-default-profile="en-alternance-broad">EN alternance</button><button class="button secondary" data-default-profile="fr-job-broad">FR job</button><button class="button secondary" data-default-profile="en-job-broad">EN job</button><div style="grid-column:1/-1;font-weight:700;font-size:10px;margin-top:6px;color:#17687a;text-transform:uppercase">Webmaster & Gestion CMS</div><button class="button secondary" data-default-profile="fr-alternance-webmaster">FR alternance</button><button class="button secondary" data-default-profile="en-alternance-webmaster">EN alternance</button><button class="button secondary" data-default-profile="fr-job-webmaster">FR job</button><button class="button secondary" data-default-profile="en-job-webmaster">EN job</button>`;}
function enhanceControls(){const font=$('#font');if(font){font.max='16';font.value=settings.font;}}
function isEnglishCv(){return (state.cv.languages||[]).some(item=>/^English\b/i.test(String(item)))||/\b(work-study|digital marketing|bilingual|native language)\b/i.test(`${state.cv.personal?.subtitle||''} ${state.cv.summary||''}`);}
function cvLabels(){return isEnglishCv()?{summary:'Summary',skills:'Skills',languages:'Languages',certifications:'Certifications',experience:'Experience',education:'Education',strategy:'Strategy & acquisition',analytics:'Data, analysis & optimisation',content:'Content & community',core:'Key skills',tools:'Tools & platforms'}:{summary:'Profil',skills:'Compétences',languages:'Langues',certifications:'Certifications',experience:'Expériences',education:'Formation',strategy:'Stratégie & acquisition',analytics:'Data, analyse & optimisation',content:'Contenu & communauté',core:'Compétences clés',tools:'Outils & plateformes'};}

function enhanceContact(){document.querySelectorAll('.contact').forEach(contact=>{const p=state.cv.personal||{};const items=[['location',p.location,'',settings.hideLocation],['phone',p.phone,`tel:${String(p.phone||'').replace(/\s/g,'')}`,settings.hidePhone],['email',p.email,`mailto:${p.email||''}`,false],['linkedin',p.linkedin,`https://${String(p.linkedin||'').replace(/^https?:\/\//,'')}`,settings.hideLinkedin],['website',p.website||'growthmaker.fr',`https://${String(p.website||'growthmaker.fr').replace(/^https?:\/\//,'')}`,settings.hideWebsite]].filter(([,value,,hidden])=>value&&!hidden);contact.innerHTML=items.map(([type,value,href])=>{const text=`<span ${settings.editMode?`contenteditable data-path="personal.${type}"`:''}>${esc(value)}</span>`;return href&&!settings.editMode?`<a class="contact-item" href="${esc(href)}" target="_blank" rel="noreferrer">${text}</a>`:`<span class="contact-item">${text}</span>`}).join('<span class="contact-sep">|</span>');});}
function localizeCv(){const labels=cvLabels();document.querySelectorAll('.cv-section>h2[data-section]').forEach(h2=>{const sec=h2.dataset.section;if(labels[sec])h2.textContent=labels[sec];});}

function shell() {
  document.querySelector('#app').innerHTML = `
    <header class="topbar"><div class="brand"><span class="brand-mark">CA</span><span>CV Adapt</span></div><div class="top-meta"><span class="privacy"><i></i> Stored locally</span><button class="button primary" id="print"><span>${settings.coverLetter ? 'Export Both' : 'Export PDF'}</span><span class="shortcut">⌘ P</span></button>${settings.coverLetter ? `<button class="button secondary" id="print-letter" style="margin-left:6px; background:#e8f4f6; color:#17687a; border:1px solid #b2d7de; font-weight:700;"><span>Export Cover Letter</span></button>` : ''}</div></header>
    <main class="workspace">
      <aside class="sidebar" aria-label="CV configuration">
        <div class="sidebar-intro"><p class="eyebrow">Workspace / 01</p><h1>Shape a sharper CV.</h1><p>Adapt your story to a role, then print a clean one-page document.</p></div>
        <section class="panel open"><button class="panel-toggle">Target role & AI Adapt <span>−</span></button><div class="panel-body"><div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:7px;"><label for="job" style="margin:0">Job description</label><button class="button secondary" id="paste-job-text" style="padding:4px 8px; font-size:10px; border-radius:4px; height:auto; min-height:0">Paste</button></div><textarea id="job" rows="7" placeholder="Paste the role description here">${esc(state.job)}</textarea><label for="priority">Priority instruction <span class="optional">Optional</span></label><input id="priority" value="${esc(state.priority)}" placeholder="e.g. Emphasize team leadership"/><label style="margin-top:10px; margin-bottom:6px; font-weight:700; display:block;">Select AI Assistant</label><div class="ai-provider-grid" style="display:flex; gap:5px; margin-bottom:12px;"><button class="button secondary provider-btn ${state.aiProvider==='gemini'?'active':''}" data-provider="gemini" style="flex:1; padding:7px 2px; font-size:10.5px; font-weight:700; cursor:pointer; border:${state.aiProvider==='gemini'?'2px solid #17687a':'1px solid #cce0e5'}; background:${state.aiProvider==='gemini'?'#e8f4f6':'#f9fbfb'}; color:${state.aiProvider==='gemini'?'#17687a':'#476170'}; border-radius:6px;">✦ Gemini</button><button class="button secondary provider-btn ${state.aiProvider==='claude'?'active':''}" data-provider="claude" style="flex:1; padding:7px 2px; font-size:10.5px; font-weight:700; cursor:pointer; border:${state.aiProvider==='claude'?'2px solid #17687a':'1px solid #cce0e5'}; background:${state.aiProvider==='claude'?'#e8f4f6':'#f9fbfb'}; color:${state.aiProvider==='claude'?'#17687a':'#476170'}; border-radius:6px;">✻ Claude</button><button class="button secondary provider-btn ${state.aiProvider==='chatgpt'?'active':''}" data-provider="chatgpt" style="flex:1; padding:7px 2px; font-size:10.5px; font-weight:700; cursor:pointer; border:${state.aiProvider==='chatgpt'?'2px solid #17687a':'1px solid #cce0e5'}; background:${state.aiProvider==='chatgpt'?'#e8f4f6':'#f9fbfb'}; color:${state.aiProvider==='chatgpt'?'#17687a':'#476170'}; border-radius:6px;">🤖 ChatGPT</button></div><button class="button adapt" id="adapt-alternance">Open in ${state.aiProvider==='claude'?'Claude':state.aiProvider==='chatgpt'?'ChatGPT':'Gemini'} (Alternance) <span>↗</span></button><button class="button adapt" id="adapt-job" style="margin-top:8px; margin-bottom:12px;">Open in ${state.aiProvider==='claude'?'Claude':state.aiProvider==='chatgpt'?'ChatGPT':'Gemini'} (Regular Job) <span>↗</span></button><button class="button paste-ai" id="paste-json" style="background:#17687a; color:#fff; font-weight:700;">📋 Paste AI JSON into CV</button><div style="margin-top:10px; display:flex; gap:6px;"><button class="button copy-ai" id="copy-prompt" style="font-size:10px; padding:6px 4px; flex:1;">Copy Alternance Prompt</button><button class="button copy-ai" id="copy-prompt-job" style="font-size:10px; padding:6px 4px; flex:1;">Copy Regular Job Prompt</button></div></div></section>
        <section class="panel open"><button class="panel-toggle">Design & layout <span>−</span></button><div class="panel-body"><label>Design</label><div class="template-grid">${['studio','minimal','slate','grid'].map(t => `<button class="template ${settings.template === t ? 'selected':''}" data-template="${t}"><span class="template-swatch ${t}"></span>${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="control-row"><label for="font">Font size</label><output id="font-out">${settings.font}px</output></div><input id="font" type="range" min="9" max="16" step=".5" value="${settings.font}"/><div class="control-row"><label for="margin">Page margins</label><output id="margin-out">${settings.margin}mm</output></div><input id="margin" type="range" min="10" max="24" value="${settings.margin}"/><div class="control-row"><label for="line">Line spacing</label><output id="line-out">${settings.line}</output></div><input id="line" type="range" min="1.1" max="1.7" step=".05" value="${settings.line}"/><label class="switch-line"><input id="photo" type="checkbox" ${settings.photo?'checked':''}/><span class="switch"></span>Show profile photo</label><label class="switch-line"><input id="cover-letter" type="checkbox" ${settings.coverLetter?'checked':''}/><span class="switch"></span>Include cover letter</label><p class="hint">Some ATS-focused applications may prefer no photo.</p></div></section>
        <section class="panel open"><button class="panel-toggle">Visible sections & contact <span>−</span></button><div class="panel-body"><label style="margin-bottom:6px; font-weight:800; display:block;">Contact items</label><label class="switch-line"><input id="hide-linkedin" type="checkbox" ${settings.hideLinkedin?'checked':''}/><span class="switch"></span>Hide LinkedIn</label><label class="switch-line"><input id="hide-website" type="checkbox" ${settings.hideWebsite?'checked':''}/><span class="switch"></span>Hide Website</label><label class="switch-line"><input id="hide-phone" type="checkbox" ${settings.hidePhone?'checked':''}/><span class="switch"></span>Hide Phone</label><label class="switch-line"><input id="hide-location" type="checkbox" ${settings.hideLocation?'checked':''}/><span class="switch"></span>Hide Location</label><label style="margin-top:14px; margin-bottom:6px; font-weight:800; display:block;">CV Sections</label><label class="switch-line"><input id="hide-summary" type="checkbox" ${settings.hideSummary?'checked':''}/><span class="switch"></span>Hide Summary / Profil</label><label class="switch-line"><input id="hide-skills" type="checkbox" ${settings.hideSkills?'checked':''}/><span class="switch"></span>Hide Skills / Compétences</label><label class="switch-line"><input id="hide-languages" type="checkbox" ${settings.hideLanguages?'checked':''}/><span class="switch"></span>Hide Languages</label><label class="switch-line"><input id="hide-certifications" type="checkbox" ${settings.hideCertifications?'checked':''}/><span class="switch"></span>Hide Certifications</label><label class="switch-line"><input id="hide-experience" type="checkbox" ${settings.hideExperience?'checked':''}/><span class="switch"></span>Hide Experience</label><label class="switch-line"><input id="hide-education" type="checkbox" ${settings.hideEducation?'checked':''}/><span class="switch"></span>Hide Education</label></div></section>
        <section class="panel"><button class="panel-toggle">CV source <span>＋</span></button><div class="panel-body"><div class="source-actions"><label class="button secondary file-label">Upload JSON<input id="upload" type="file" accept="application/json"/></label><button class="button secondary" id="reset">Reset French</button></div><div class="cv-language-actions"><button class="button secondary" id="default-fr">French default</button><button class="button secondary" id="default-en">English default</button></div><textarea class="json-editor" id="json" rows="8">${esc(JSON.stringify(state.cv,null,2))}</textarea><p class="validation ${state.jsonError?'error':''}" id="validation">${state.jsonError || 'Valid CV JSON. Saved locally.'}</p></div></section>
        <section class="panel"><button class="panel-toggle">AI Workflow Guide <span>＋</span></button><div class="panel-body"><p style="font-size:12px; line-height:1.45; color:#476170; margin-bottom:8px;">No API key needed! CV Adapt copies your tailored prompt directly and opens <strong>Gemini</strong> or <strong>Claude</strong> in a new tab.</p><ol style="font-size:11.5px; padding-left:18px; margin:0; line-height:1.6; color:#2c404d;"><li>Click <strong>Open in Gemini/Claude</strong> above.</li><li>Press <strong>Ctrl + V</strong> in the AI window and hit Enter.</li><li>Copy the JSON response from AI.</li><li>Click <strong>Paste AI JSON into CV</strong>.</li></ol></div></section>
      </aside>
      <section class="canvas"><div class="canvas-head"><div><p class="eyebrow">Live document / A4</p><h2>${state.adapted ? 'Adapted CV' : 'Ready to adapt'}</h2></div><div class="canvas-tools"><button class="button edit-switch ${settings.editMode?'active':''}" id="edit-mode">${settings.editMode?'Finish editing':'Edit CV'}</button><div class="score-mini"><span>ATS match</span><strong>${ats().score}<small>/100</small></strong></div></div></div><nav class="tabs" role="tablist">${['original','adapted','changes','ai'].map(t => `<button class="tab ${state.tab===t?'active':''}" data-tab="${t}">${t[0].toUpperCase()+t.slice(1)}${t==='changes'?'<sup>3</sup>':''}</button>`).join('')}</nav><div class="canvas-content">${state.tab === 'changes' ? changesView() : state.tab === 'ai' ? aiView() : previewView()}</div></section>
    </main><div class="toast" role="status"></div>`;
  addTopDefaults(); addTemplateChoices(); addDefaultDesignControl(); addDefaultSourceControls(); enhanceControls(); bind(); renderPreview(); renderFilename();
}

function ats() { const text = JSON.stringify(state.cv).toLowerCase(); const job = state.job.toLowerCase(); const keywords = [...new Set((job.match(/[a-z][a-z+#&]{3,}/g)||[]).filter(k=>!['with','that','this','will','your','from','have','they','you','lead','role'].includes(k)))]; const hits=keywords.filter(k=>text.includes(k)); let score=50+Math.min(30, hits.length*4)+(state.cv.personal.email?5:0)+(state.cv.personal.phone?5:0)+(state.cv.experience?.length?5:0)+(state.cv.summary?5:0); return {score:Math.min(100,score), keywords, hits}; }
function previewView() { 
  let html = `<article class="cv-paper ${settings.template}" style="--cv-font:${settings.font}px;--cv-margin:${settings.margin}mm;--cv-line:${settings.line}">${settings.editMode?cvMarkup():staticCvMarkup()}</article>`;
  if(settings.coverLetter) {
    html += `<article class="cv-paper cover-letter-page ${settings.template}" style="margin-top:20px;--cv-font:${settings.font}px;--cv-margin:${settings.margin}mm;--cv-line:${settings.line}">${settings.editMode?coverLetterMarkup():staticCoverLetterMarkup()}</article>`;
  }
  return `<div class="paper-wrap"><span class="a4-label">210 × 297 mm</span>${html}</div>`; 
}
function skillRelevance(item){const job=String(state.job||'').toLowerCase();return String(item).toLowerCase().split(/[^\p{L}\p{N}+#]+/u).filter(word=>word.length>2&&job.includes(word)).length;}
function skillGroups(){const source=state.cv.skills||[];const items=state.adapted?[...source].sort((a,b)=>skillRelevance(b)-skillRelevance(a)):source;const labels=cvLabels();const patterns={tools:/\b(ga4|google analytics|looker|tag manager|gtm|semrush|ahrefs|wordpress|hubspot|salesforce|figma|notion|airtable|canva|adobe|photoshop|illustrator|premiere|html|css|meta ads|google ads|linkedin campaign|mailchimp|brevo|make|zapier|excel|power bi|admob|audience network)\b/i,content:/content|social|community|communaut|rédaction|redaction|writing|copywriting|editorial|éditorial|storytelling|communication|video/i,analytics:/data|analyse|analysis|reporting|insight|measurement|mesure|dashboard|attribution|automatisation|automation|\bia\b|artificial intelligence/i,strategy:/seo|sea|aso|acquisition|growth|strategie|stratégie|cro|funnel|conversion|lifecycle|retention|monetisation|monétisation|campaign|campagne/i};const buckets=[[labels.strategy,[]],[labels.analytics,[]],[labels.content,[]],[labels.core,[]],[labels.tools,[]]];for(const item of items){const target=patterns.tools.test(item)?4:patterns.content.test(item)?2:patterns.analytics.test(item)?1:patterns.strategy.test(item)?0:3;buckets[target][1].push(item);}const groups=buckets.filter(([,list])=>list.length);const small=groups.filter(([,list])=>list.length===1);let result=groups.filter(([,list])=>list.length>1);if(small.length>=2)result.push([labels.core,small.flatMap(([,list])=>list)]);else if(small.length===1){const single=small[0][1];const destination=result.find(([label])=>label!==labels.tools)||result[0];if(destination)destination[1].push(...single);else result.push([labels.core,single]);}return result;}
function certificationParts(item){const str=String(item);const idx=str.lastIndexOf(' - ');return idx!==-1?{name:str.slice(0,idx).trim(),issuer:str.slice(idx+3).trim()}:{name:str,issuer:''};}
function staticCvMarkup(){return cvMarkup().replace(/\scontenteditable data-path="[^"]+"/g,'');}
function staticCoverLetterMarkup(){return coverLetterMarkup().replace(/\scontenteditable data-path="[^"]+"/g,'');}
function coverLetterMarkup(){const p=state.cv.personal;const isEn=isEnglishCv();const dateStr=new Date().toLocaleDateString(isEn?'en-GB':'fr-FR',{year:'numeric',month:'long',day:'numeric'});const defaultGreeting=isEn?'Dear Hiring Manager,':'Madame, Monsieur,';const defaultP1=isEn?'I am writing to express my strong interest in the position.':'Je vous adresse ma candidature pour le poste à pourvoir au sein de votre entreprise.';const defaultP2=isEn?'I would welcome the opportunity to discuss how my background, skills, and certifications will be of added value to your organization. I am available for an interview at your earliest convenience.':'Je me tiens à votre entière disposition pour échanger de vive voix sur ma candidature et serais ravi de vous rencontrer lors d\'un entretien.';const defaultSignoff=isEn?'Sincerely,':'Veuillez agréer, Madame, Monsieur, l\'expression de mes salutations distinguées.';const letter=state.cv.coverLetter||{};const greeting=letter.greeting||defaultGreeting;const paragraph=letter.paragraph||defaultP1;const closing=letter.closing||defaultP2;const signoff=letter.signoff||defaultSignoff;return `<div class="cv-header"><div class="cv-header-top">${settings.photo?`<img class="profile-photo" src="${esc(avatar())}" onerror="this.onerror=null;this.src='profile-default.png'" alt="Profile photo"/>`:''}<div class="identity"><h1 contenteditable data-path="personal.name">${esc(p.name)}</h1><p class="role" contenteditable data-path="personal.role">${esc(p.role)}</p></div></div><div class="contact"><span contenteditable data-path="personal.location">${esc(p.location)}</span><span contenteditable data-path="personal.phone">${esc(p.phone)}</span><span contenteditable data-path="personal.email">${esc(p.email)}</span><span contenteditable data-path="personal.linkedin">${esc(p.linkedin)}</span></div></div><section class="cv-section cover-letter-body" style="margin-top:40px; font-size: 1.05em; line-height: 1.6;"><p style="margin-bottom:30px; text-align:right;">${dateStr}</p><p contenteditable data-path="coverLetter.greeting" style="margin-bottom:20px; font-weight:600;">${esc(greeting)}</p><p contenteditable data-path="coverLetter.paragraph" style="margin-bottom:20px;">${esc(paragraph)}</p><p contenteditable data-path="coverLetter.closing" style="margin-bottom:30px;">${esc(closing)}</p><p contenteditable data-path="coverLetter.signoff" style="margin-bottom:15px;">${esc(signoff)}</p><p contenteditable data-path="personal.name" style="font-weight:600;">${esc(p.name)}</p></section>`;}
function enhanceLanguages(){if(settings.editMode)return;const heading=document.querySelector('.cv-section h2[data-section="languages"]');const text=heading?.nextElementSibling;if(!text||text.dataset.enhanced)return;const languages=text.textContent.split(/\s*\/\s*/).map(item=>item.trim()).filter(Boolean);text.className='language-grid';text.innerHTML=languages.map(language=>{const [name,...level]=language.split(/\s*-\s*/);return `<span class="language-chip"><strong>${esc(name)}</strong>${level.length?`<small>${esc(level.join(' - '))}</small>`:''}</span>`}).join('');text.dataset.enhanced='true';}
function cvMarkup() { const p=state.cv.personal; const skills=skillGroups().map(([label,list])=>`<div class="skill-row"><span>${esc(label)}</span><p>${list.map(esc).join(' · ')}</p></div>`).join('');const certifications=(state.cv.certifications||[]).map(item=>{const cert=certificationParts(item);return `<li><strong>${esc(cert.name)}</strong>${cert.issuer?`<span>${esc(cert.issuer)}</span>`:''}</li>`}).join('');return `<div class="cv-header"><div class="cv-header-top">${settings.photo ? `<img class="profile-photo" src="${esc(avatar())}" onerror="this.onerror=null;this.src='profile-default.png'" alt="Profile photo"/>` : ''}<div class="identity"><h1 contenteditable data-path="personal.name">${esc(p.name)}</h1><p class="role" contenteditable data-path="personal.role">${esc(p.role)}</p><p class="subtitle" contenteditable data-path="personal.subtitle">${esc(p.subtitle)}</p></div></div><div class="contact"><span contenteditable data-path="personal.location">${esc(p.location)}</span><span contenteditable data-path="personal.phone">${esc(p.phone)}</span><span contenteditable data-path="personal.email">${esc(p.email)}</span><span contenteditable data-path="personal.linkedin">${esc(p.linkedin)}</span></div></div>`+(!settings.hideSummary&&state.cv.summary?`<section class="cv-section"><h2 data-section="summary">Summary</h2><p contenteditable data-path="summary">${esc(state.cv.summary)}</p></section>`:'')+(!settings.hideSkills&&skills?`<section class="cv-section"><h2 data-section="skills">Skills</h2><div class="skill-groups">${skills}</div></section>`:'')+(!settings.hideLanguages&&state.cv.languages?.length?`<section class="cv-section"><h2 data-section="languages">Languages</h2><p contenteditable data-path="languages">${state.cv.languages.map(esc).join('  /  ')}</p></section>`:'')+(!settings.hideCertifications&&certifications?`<section class="cv-section"><h2 data-section="certifications">Certifications</h2><ul class="credential-list">${certifications}</ul></section>`:'')+(!settings.hideExperience&&state.cv.experience?.length?`<section class="cv-section"><h2 data-section="experience">Experience</h2>${state.cv.experience.map((e,i)=>`<div class="cv-item"><div class="item-top"><h3 contenteditable data-path="experience.${i}.title">${esc(e.title)}</h3><span contenteditable data-path="experience.${i}.dates">${esc(e.dates)}</span></div><p class="company"><span contenteditable data-path="experience.${i}.company">${esc(e.company)}</span> · <span contenteditable data-path="experience.${i}.location">${esc(e.location)}</span></p><ul>${e.bullets.map((b,j)=>`<li contenteditable data-path="experience.${i}.bullets.${j}">${esc(b)}</li>`).join('')}</ul></div>`).join('')}</section>`:'')+(!settings.hideEducation&&state.cv.education?.length?`<section class="cv-section"><h2 data-section="education">Education</h2>${state.cv.education.map((e,i)=>`<div class="cv-item"><div class="item-top"><h3 contenteditable data-path="education.${i}.degree">${esc(e.degree)}</h3><span contenteditable data-path="education.${i}.dates">${esc(e.dates)}</span></div><p class="company"><span contenteditable data-path="education.${i}.institution">${esc(e.institution)}</span> · <span contenteditable data-path="education.${i}.location">${esc(e.location)}</span></p><p contenteditable data-path="education.${i}.description">${esc(e.description)}</p></div>`).join('')}</section>`:''); }
function changesView(){ return `<div class="insight-page"><p class="eyebrow">Adaptation notes</p><h2>Three useful shifts</h2><div class="change"><span>01</span><div><strong>Search visibility</strong><p>Bring SEO strategy, technical audits, and organic revenue into the top half of the page.</p></div></div><div class="change"><span>02</span><div><strong>Leadership signal</strong><p>Keep the team size and cross-functional partnership language. These are strong role matches.</p></div></div><div class="change"><span>03</span><div><strong>Proof over promise</strong><p>Quantified outcomes are doing the heavy lifting. Keep the 42%, 31%, 28%, and 18% results.</p></div></div></div>`; }
function aiView(){ return `<div class="insight-page"><p class="eyebrow">Web AI Workflow</p><h2>Adapt with Gemini, Claude, or ChatGPT in your browser.</h2><p class="lead">No API key or complex setup required. Choose your favorite AI assistant, generate your tailored prompt in 1 click, and paste the returned JSON directly back into your CV.</p><div class="ai-callout" style="margin-bottom:15px;"><span class="ai-orb">✦</span><div><strong>Google Gemini</strong><p>Fast and accurate. Prompt copied to clipboard → open gemini.google.com and press Ctrl+V.</p></div></div><div class="ai-callout" style="margin-bottom:15px;"><span class="ai-orb" style="background:linear-gradient(135deg,#d97706,#b45309)">✻</span><div><strong>Anthropic Claude</strong><p>Exceptional editorial nuance. Prompt copied to clipboard → open claude.ai and press Ctrl+V.</p></div></div><div class="ai-callout"><span class="ai-orb" style="background:linear-gradient(135deg,#10a37f,#059669)">🤖</span><div><strong>OpenAI ChatGPT</strong><p>Direct pre-fill supported! Prompt is loaded directly into chatgpt.com text input field.</p></div></div></div>`; }
function bind(){ document.querySelectorAll('.panel-toggle').forEach(b=>b.onclick=()=>b.parentElement.classList.toggle('open')); document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{settings.template=b.dataset.template;shell()}); document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;shell()}); $('#adapt-alternance').onclick=()=>openInAI(state.aiProvider,'alternance'); $('#adapt-job').onclick=()=>openInAI(state.aiProvider,'job'); document.querySelectorAll('.provider-btn').forEach(btn=>btn.onclick=()=>{state.aiProvider=btn.dataset.provider;localStorage.setItem('cv-adapt-provider',state.aiProvider);shell();}); $('#edit-mode').onclick=()=>{settings.editMode=!settings.editMode;toast(settings.editMode?'Editing enabled. Turn it off before exporting.':'Editing disabled. The CV is ready to export.');shell()}; $('#print').onclick=()=>exportPdf('all'); if($('#print-letter')) $('#print-letter').onclick=()=>exportPdf('letter'); $('#job').oninput=e=>state.job=clean(e.target.value); $('#priority').oninput=e=>state.priority=clean(e.target.value); $('#reset').onclick=()=>{state.cv=JSON.parse(JSON.stringify(defaultCv));save();toast('Default CV restored');shell()}; $('#photo').onchange=e=>{settings.photo=e.target.checked;renderPreview()}; $('#cover-letter').onchange=e=>{settings.coverLetter=e.target.checked;if(settings.coverLetter&&!state.cv.coverLetter){state.cv.coverLetter={};save();}shell();}; $('#font').oninput=e=>{settings.font=e.target.value;updateControls();renderPreview()}; $('#margin').oninput=e=>{settings.margin=e.target.value;updateControls();renderPreview()}; $('#line').oninput=e=>{settings.line=e.target.value;updateControls();renderPreview()}; $('#hide-linkedin').onchange=e=>{settings.hideLinkedin=e.target.checked;renderPreview()}; $('#hide-website').onchange=e=>{settings.hideWebsite=e.target.checked;renderPreview()}; $('#hide-phone').onchange=e=>{settings.hidePhone=e.target.checked;renderPreview()}; $('#hide-location').onchange=e=>{settings.hideLocation=e.target.checked;renderPreview()}; $('#hide-summary').onchange=e=>{settings.hideSummary=e.target.checked;renderPreview()}; $('#hide-skills').onchange=e=>{settings.hideSkills=e.target.checked;renderPreview()}; $('#hide-languages').onchange=e=>{settings.hideLanguages=e.target.checked;renderPreview()}; $('#hide-certifications').onchange=e=>{settings.hideCertifications=e.target.checked;renderPreview()}; $('#hide-experience').onchange=e=>{settings.hideExperience=e.target.checked;renderPreview()}; $('#hide-education').onchange=e=>{settings.hideEducation=e.target.checked;renderPreview()}; $('#json').oninput=e=>{try{const next=JSON.parse(e.target.value);state.cv=next;state.jsonError='';save();$('#validation').textContent='Valid CV JSON. Saved locally.';$('#validation').classList.remove('error');renderPreview()}catch(err){state.jsonError='JSON needs attention: '+err.message;$('#validation').textContent=state.jsonError;$('#validation').classList.add('error')}}; $('#upload').onchange=e=>{const f=e.target.files[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{$('#json').value=reader.result;$('#json').dispatchEvent(new Event('input'));toast('CV JSON imported')};reader.readAsText(f)}; document.addEventListener('blur', editHandler, true); }

async function exportPdf(mode='all'){
  if(state.tab==='changes'||state.tab==='ai'){state.tab='adapted';shell()}
  const isLetterOnly = mode === 'letter';
  toast(`Generating ${isLetterOnly ? 'Cover Letter' : 'PDF'}... please wait.`);
  setPrintEditState(false);
  const fit = calculatePrintFit();
  const scale = fit.scale || 1;
  let css = `:root { --print-scale: ${scale.toFixed(3)} !important; }\n`;
  for(const sheet of document.styleSheets){
    try {
      if(sheet.href){
        if(sheet.href.startsWith(window.location.origin)){
          const res=await fetch(sheet.href);
          css+=await res.text();
        }
      } else {
        css+=Array.from(sheet.cssRules).map(r=>r.cssText).join('');
      }
    }catch(e){}
  }

  let selector = '.cv-paper';
  if(mode === 'cv') selector = '.cv-paper:not(.cover-letter-page)';
  else if(mode === 'letter') selector = '.cv-paper.cover-letter-page';

  const papers = Array.from(document.querySelectorAll(selector));
  if(!papers.length){
    toast('No document found to export.');
    setPrintEditState(settings.editMode);
    return;
  }
  const html = papers.map(p => p.outerHTML).join('\n');
  const pdfApi = window.location.port === '3000' ? '/api/export-pdf' : 'http://localhost:3000/api/export-pdf';
  try {
    const res=await fetch(pdfApi,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({html,css,coverLetter:isLetterOnly})});
    if(!res.ok) {
      const errText = await res.text().catch(()=>'');
      throw new Error(errText || `Server error (${res.status})`);
    }
    const blob=await res.blob();
    const url=window.URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url;
    let downloadName = suggestedFilename();
    if(isLetterOnly) {
      const title = state.cv.personal.role || jobTitle();
      downloadName = `Lettre_de_Motivation_${filenamePart(state.cv.personal.name)}_${filenamePart(title)}`;
    }
    a.download=downloadName+'.pdf';
    document.body.appendChild(a);
    a.click();
    window.URL.revokeObjectURL(url);
    document.body.removeChild(a);
    toast(isLetterOnly ? 'Cover Letter PDF downloaded successfully' : (scale < 0.995 ? `PDF exported (auto-scaled to ${Math.round(scale*100)}% for 1 A4 page)` : 'PDF downloaded successfully'));
  }catch(err){
    toast('Error: '+(err.message || 'Is server.js running on port 3000?'));
  }finally{
    setPrintEditState(settings.editMode);
    document.documentElement.style.setProperty('--print-scale','.9');
  }
}
function editHandler(e){if(!e.target.matches('[contenteditable][data-path]'))return;const path=e.target.dataset.path.split('.');let obj=state.cv;for(let i=0;i<path.length-1;i++)obj=obj[path[i]];const key=path.at(-1);const value=clean(e.target.innerText.replace(/\s+\/\s+/g,', '));obj[key]=['skills','languages','certifications'].includes(path[0])?value.split(',').map(v=>v.trim()).filter(Boolean):value;save();}
function updateControls(){ $('#font-out').textContent=settings.font+'px';$('#margin-out').textContent=settings.margin+'mm';$('#line-out').textContent=settings.line; }
function renderPreview(){const paper=$('.paper-wrap');if(!paper)return;const html=`<article class="cv-paper ${settings.template}" style="--cv-font:${settings.font}px;--cv-margin:${settings.margin}mm;--cv-line:${settings.line}">${settings.editMode?cvMarkup():staticCvMarkup()}</article>`+(settings.coverLetter?`<article class="cv-paper cover-letter-page ${settings.template}" style="margin-top:20px;--cv-font:${settings.font}px;--cv-margin:${settings.margin}mm;--cv-line:${settings.line}">${settings.editMode?coverLetterMarkup():staticCoverLetterMarkup()}</article>`:'');paper.innerHTML=`<span class="a4-label">210 × 297 mm</span>${html}`;enhanceLanguages();enhanceContact();localizeCv();renderFilename();}
function setPrintEditState(editable){document.querySelectorAll('.cv-paper [contenteditable]').forEach(el=>el.setAttribute('contenteditable',editable?'true':'false'));}
function calculatePrintFit(){const paper=$('.cv-paper');if(!paper)return {scale:1,height:0};document.documentElement.style.setProperty('--print-scale','1');const clone=paper.cloneNode(true);clone.classList.add('print-measure');clone.style.cssText='position:fixed!important;left:-10000px!important;top:0!important;width:210mm!important;height:auto!important;min-height:0!important;max-height:none!important;zoom:1!important;transform:none!important;visibility:hidden!important;';document.body.append(clone);const height=clone.getBoundingClientRect().height;clone.remove();let scale=1065/(height||1065);scale=Math.min(1.22,Math.max(0.68,scale));document.documentElement.style.setProperty('--print-scale',scale.toFixed(3));return {scale,height};}
function reportPrintFit(){const fit=calculatePrintFit();if(!fit.height)return;toast(fit.scale<.995?`CV is long. Print will compact it to one A4 page (${Math.round(fit.scale*100)}%).`:'Print check: fits on one A4 page.');}
async function pasteJsonFromClipboard(){try{const raw=await navigator.clipboard.readText();const json=raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const next=JSON.parse(json);if(!next.personal||!Array.isArray(next.experience)||!Array.isArray(next.education))throw new Error('shape');state.cv=next;save();shell();toast('AI JSON pasted into your CV.')}catch(error){toast('Clipboard does not contain valid CV JSON.')}}

function openInAI(provider = state.aiProvider || 'gemini', track = 'alternance'){
  state.track = track;
  state.aiProvider = provider;
  localStorage.setItem('cv-adapt-track', track);
  localStorage.setItem('cv-adapt-provider', provider);
  
  const prompt = promptText(track);
  let providerName = 'Gemini';
  let targetUrl = 'https://gemini.google.com/app';
  
  if (provider === 'claude') {
    providerName = 'Claude';
    targetUrl = 'https://claude.ai/new';
  } else if (provider === 'chatgpt') {
    providerName = 'ChatGPT';
    targetUrl = `https://chatgpt.com/?q=${encodeURIComponent(prompt)}`;
  }
  
  if (provider === 'chatgpt') {
    copyText(prompt, `Opening ChatGPT with pre-filled prompt... Just hit Enter!`);
  } else {
    copyText(prompt, `${providerName} prompt copied! Opening ${providerName}... Press Ctrl+V to paste.`);
  }
  
  setTimeout(() => {
    window.open(targetUrl, '_blank');
  }, 350);
}
const adaptWithGemini = (track) => openInAI('gemini', track);
const adaptWithClaude = (track) => openInAI('claude', track);
const adaptWithGroq = openInAI;

async function copyText(value,message){try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard API unavailable');await navigator.clipboard.writeText(value);toast(message);}catch(error){const field=document.createElement('textarea');field.value=value;field.setAttribute('readonly','');field.style.cssText='position:fixed;left:-9999px;top:0;opacity:0';document.body.append(field);field.select();const copied=document.execCommand('copy');field.remove();toast(copied?message:'Could not copy text. Try again.');}}
document.addEventListener('click',event=>{const profileChoice=event.target.closest('[data-default-profile]');if(profileChoice){const val=profileChoice.dataset.defaultProfile;const withCL=val.endsWith('-cl');const clean=withCL?val.slice(0,-3):val;const parts=clean.split('-');const lang=parts[0]||'fr';const track=parts[1]||'alternance';const variant=parts[2]||'growth';loadDefaultCv(lang,track,variant,withCL);}const defaultChoice=event.target.closest('[data-default-lang]');if(defaultChoice)loadDefaultCv(defaultChoice.dataset.defaultLang);if(event.target.closest('#paste-job-text')){navigator.clipboard.readText().then(text=>{if(text){state.job=text;save();shell();toast('Job description pasted.');}}).catch(()=>toast('Could not read clipboard.'));}if(event.target.closest('#paste-json'))pasteJsonFromClipboard();if(event.target.closest('#default-fr'))loadDefaultCv('fr','alternance',state.variant);if(event.target.closest('#default-en'))loadDefaultCv('en','alternance',state.variant);if(event.target.closest('#copy-filename'))copyText(suggestedFilename(),'CV file name copied.');if(event.target.closest('#copy-prompt'))copyText(promptText('alternance'),'Alternance AI prompt copied to clipboard');if(event.target.closest('#copy-prompt-job'))copyText(promptText('job'),'Regular-job AI prompt copied to clipboard');});
document.addEventListener('input',event=>{if(event.target.matches('#job'))setTimeout(renderFilename);});
document.addEventListener('click',event=>{if(event.target.closest('#set-default-template'))setDefaultDesign();});
window.addEventListener('beforeprint',()=>{setPrintEditState(false);calculatePrintFit();});window.addEventListener('afterprint',()=>{setPrintEditState(settings.editMode);document.documentElement.style.setProperty('--print-scale','.9');});

function promptText(track='alternance'){
  const language=targetLanguage();
  const source=defaultCvFor(language==='English'?'en':'fr',track);
  const trackName=track==='job'?'REGULAR JOB (FULL-TIME / PERMANENT)':'ALTERNANCE (WORK-STUDY)';

  return `Create a ${track==='job'?'regular job':'work-study (alternance)'} CV from the DEFAULT SOURCE CV (${trackName}) and TARGET JOB DESCRIPTION below. Always start from this default CV, even if another adapted CV was previously pasted into the application.\n\nSTRICT OUTPUT CONTRACT:\n1. Return ONLY one valid JSON object. The first character must be { and the last character must be }. No markdown fences, comments, explanations, or text outside JSON.\n2. Preserve the exact source schema, field names, nested object shapes, and array types. Do not add, remove, or rename fields. The result must work with JSON.parse.\n3. Keep contact details, employers, institutions, locations, dates, certifications, factual metrics, and URLs accurate. Do not invent employment, achievements, credentials, responsibilities, or results.\n4. OUTPUT LANGUAGE: ${language}. Write every candidate-facing field in ${language}. Keep names, employers, locations, dates, contact details, URLs, and filenames unchanged.\n5. Rewrite personal.role each time as a simple 2-5 word job title that fits the position and is supported by the CV.\n\nSKILLS & KEYWORD MATCHING (CRITICAL):\n6. JOB ANALYSIS: First, deeply analyze the TARGET JOB DESCRIPTION to identify the most crucial keywords, core competencies, and specific software tools the employer requires.\n7. REALISTIC MAPPING: Compare these employer requirements with the DEFAULT SOURCE CV. When you find a genuine match or a highly transferable skill, use the EXACT terminology and keywords from the job description in the CV. This ensures ATS compliance and recruiter resonance.\n8. MASTER SKILLS LIST & INFERENCE: The DEFAULT SOURCE CV contains a master list of the candidate's tools and skills. Pick the BEST ones for this specific job. Additionally, if the job description demands other easy-to-use tools or similar tools to the ones the candidate already knows (e.g. asking for Trello/Asana, or asking for Ahrefs when the candidate knows Semrush), you MUST add them to the skills array and experience bullets to ensure a perfect match.\n9. THE SKILLS ARRAY: Return 10-14 focused strings. Select the most relevant tools from the master list, and intelligently inject any similar/easy-to-use tools demanded by the job. Use the exact keywords from the job offer. Keep capabilities separate from tools.\n9a. TOOL INFERENCE: If the job asks for a capability (e.g., SEO, Analytics) but no specific tool, proactively surface the most relevant tools from the source CV (e.g., Semrush, GA4) to prove you can execute that capability.\n\nCOVER LETTER:\n11. Add a new object to the root of the JSON called "coverLetter". Inside it, provide exactly one string field called "paragraph".\n12. This "paragraph" must be a highly personalized, natural, and simple paragraph (3-5 sentences) written in ${language}. Use a conversational but professional tone—avoid overly formal, robotic, or bloated corporate jargon. It should explicitly connect the candidate's background to the core needs of this specific role, demonstrating enthusiasm and immediate value. NOTE: The candidate is male, so strictly use masculine grammatical agreement in French (e.g., "Je suis prêt", not "Je suis prête").\n\nPERSONALISATION:\n13. Make the summary, role title, skills, experience bullets, and education descriptions tell one coherent story for this role, integrating the job's crucial keywords naturally. Keep the writing concise, never generic.\n14. Treat Freelance Growth & Digital as an adaptable evidence base for app growth, ASO, acquisition, monetisation, WordPress, creative production, and client projects. Tailor the English and Linguistics degree toward relevant bilingual communication, writing, editorial analysis, content, and cross-cultural skills.\n15. Use at most 3 concise, achievement-focused bullets per experience. Preserve numbers exactly when present. Keep the full CV suitable for one A4 page.\n16. Use normal hyphens only, never em dashes or en dashes.\n17. NEVER mention the name of the company hiring for this role anywhere in the CV or Cover Letter, neither in French nor in English. Do not use phrases like "Excited to join [Company]" or "Ravi de rejoindre [Company]". The content must look naturally tailored to the role, but entirely independent of the specific company name.\n\nBefore answering, silently check: valid JSON, exact schema, correct language, clear role title, a newly tailored skills array, the added coverLetter object, only credible claims, no target company names, and concise one-page content.\n\nDEFAULT SOURCE CV JSON (${trackName}):\n${JSON.stringify(source,null,2)}\n\nTARGET JOB DESCRIPTION:\n${state.job}\n\nPRIORITY INSTRUCTION:\n${state.priority||'None.'}`;
}
function toast(msg){const t=$('.toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
